        return 'Control Structures'
    elif any(w in q for w in ['operator', 'arithmetic', 'logical', 'increment', 'decrement', 'modulus', 'relational', 'assignment']):
        return 'Operators'
    elif any(w in q for w in ['printf', 'scanf', 'output', 'input', 'format specifier', 'getch', 'gets', 'putchar']):
        return 'Input/Output'
    elif any(w in q for w in ['function', 'return', 'void', 'parameter', 'recursive', 'recursion']):
        return 'Functions'
