        return 'Database & DBMS'
    elif any(w in q for w in ['ms-access', 'access', 'form', 'report', 'query', 'macro', 'module']):
        return 'MS Access'
    elif any(w in q for w in ['data type', 'int', 'float', 'char', 'double', 'string', 'void', 'variable', 'constant']):
        return 'Data Types & Variables'
    elif any(w in q for w in ['file', 'fopen', 'fclose', 'fprintf', 'fscanf']):
        return 'File Handling'
    elif any(w in q for w in ['algorithm', 'flowchart', 'program', 'code']):
        return 'Programming Basics'
    elif any(w in q for w in ['array', 'pointer', 'structure', 'union']):
        return 'Advanced Data Structures'
    else:
        return 'Other'

df['topic'] = df.apply(lambda r: classify_topic(r['question'], r['type']), axis=1)
print('Topic distribution:')
print(df['topic'].value_counts())
print()
print('Topic by year:')
ct = df.groupby(['year','topic']).size().unstack(fill_value=0)
print(ct)
